def prefixConnected(words, k):
    # Count how many words share each k-length prefix
    groups = {}
    for w in words:
        # Words shorter than k cannot join any group
        if len(w) >= k:
            prefix = w[:k]
            groups[prefix] = groups.get(prefix, 0) + 1

    # A group needs at least two words
    ans = 0
    for count in groups.values():
        if count >= 2:
            ans += 1
    return ans
